using dcomp = std::complex<double>;

std::vector<dcomp> calculate_mode_annihilation_diagonal(size_t cutoff) {
    std::vector<dcomp> result;
    result.reserve(cutoff - 1);

    for (size_t n = 0; n < cutoff - 1; ++n) {
        result.emplace_back(std::sqrt(n + 1));
    }

    return result;
}

